/// <summary>
/// Helper for ABN validation telemetry. All telemetry calls are guarded so that a
/// telemetry failure can never break the ABN validation process.
/// </summary>
internal final class METABNValidationTelemetryHelper
{
    #define.MessageSeparator('\n')
    #define.TimeoutTypeName('TimeoutException')
    #define.TaskCancelledTypeName('TaskCanceledException')
    #define.TimedOutText('timed out')
    #define.TimeoutText('timeout')

}

Method.Source:
/// <summary>
/// Logs a successful ABN web service call.
/// </summary>
/// <param name = "_queue">Queue record being processed.</param>
/// <param name = "_durationMilliseconds">Elapsed time of the call.</param>
public static void logSuccess(METABNValidationJobQueue _queue, int64 _durationMilliseconds)
{
    try
    {
        METTelemetryABNValidationEvent::runTelemetryEvent(_queue, _durationMilliseconds);
    }
    catch
    {
        // Telemetry is non-functional. Never let it break ABN validation.
        Global::exceptionTextFallThrough();
    }
}

/// <summary>
/// Logs a failed ABN web service call, including timeouts.
/// </summary>
/// <param name = "_queue">Queue record being processed.</param>
/// <param name = "_failureType">Classification of the failure.</param>
/// <param name = "_errorMessage">Error details.</param>
/// <param name = "_durationMilliseconds">Elapsed time before the failure.</param>
public static void logFailure(METABNValidationJobQueue _queue,
                              str                      _failureType,
                              str                      _errorMessage,
                              int64                    _durationMilliseconds)
{
    try
    {
        METTelemetryABNValidationErrorEvent::runTelemetryEvent(_queue, _failureType, _errorMessage, _durationMilliseconds);
    }
    catch
    {
        Global::exceptionTextFallThrough();
    }
}

/// <summary>
/// Reads infolog messages in the given line range without clearing the infolog.
/// </summary>
/// <param name = "_fromLine">First line to read.</param>
/// <param name = "_toLine">Last line to read.</param>
/// <returns>Concatenated infolog messages.</returns>
public static str infologMessages(int _fromLine, int _toLine)
{
    str                     message = '';
    SysInfologEnumerator    enumerator;
    SysInfologMessageStruct msgStruct;

    if (_toLine < _fromLine || _fromLine <= 0)
    {
        return message;
    }

    enumerator = SysInfologEnumerator::newData(infolog.copy(_fromLine, _toLine));

    while (enumerator.moveNext())
    {
        msgStruct = new SysInfologMessageStruct(enumerator.currentMessage());
        message  += msgStruct.message() + #MessageSeparator;
    }

    return message;
}

/// <summary>
/// Flattens a CLR exception and all its inner exceptions into a single message.
/// </summary>
/// <param name = "_exception">CLR exception.</param>
/// <returns>Concatenated exception messages.</returns>
public static str clrExceptionMessage(System.Exception _exception)
{
    str              message = '';
    System.Exception currentException = _exception;

    while (currentException != null)
    {
        message += currentException.GetType().get_FullName()
                 + ': '
                 + currentException.get_Message()
                 + #MessageSeparator;

        currentException = currentException.get_InnerException();
    }

    return message;
}

/// <summary>
/// Classifies a CLR exception as a timeout or a generic service error.
/// </summary>
/// <param name = "_exception">CLR exception.</param>
/// <returns>The failure type.</returns>
public static str failureTypeFromClrException(System.Exception _exception)
{
    str              failureType      = METABNValidationFailureTypes::ServiceError;
    System.Exception currentException = _exception;
    str              typeName, exceptionMessage;

    while (currentException != null)
    {
        typeName         = currentException.GetType().get_FullName();
        exceptionMessage = strLwr(currentException.get_Message());

        if (strScan(typeName, #TimeoutTypeName, 1, strLen(typeName))
         || strScan(typeName, #TaskCancelledTypeName, 1, strLen(typeName))
         || strScan(exceptionMessage, #TimedOutText, 1, strLen(exceptionMessage))
         || strScan(exceptionMessage, #TimeoutText, 1, strLen(exceptionMessage)))
        {
            failureType = METABNValidationFailureTypes::Timeout;
            break;
        }

        currentException = currentException.get_InnerException();
    }

    return failureType;
}

/// <summary>
/// Classifies a service error message as a timeout or a generic service error.
/// Used when <c>METWebService</c> handles the transport exception internally and
/// surfaces it as an error string rather than a CLR exception.
/// </summary>
/// <param name = "_errorMessage">Error message returned by the web service.</param>
/// <returns>The failure type.</returns>
public static str failureTypeFromMessage(str _errorMessage)
{
    str failureType  = METABNValidationFailureTypes::ServiceError;
    str lowerMessage = strLwr(_errorMessage);

    if (strScan(lowerMessage, #TimedOutText, 1, strLen(lowerMessage))
     || strScan(lowerMessage, #TimeoutText, 1, strLen(lowerMessage)))
    {
        failureType = METABNValidationFailureTypes::Timeout;
    }

    return failureType;
}
